use std::rc::Rc;
use std::thread;

pub fn run() -> usize {
    let data = Rc::new(vec![1, 2, 3, 4]);
    let mut handles = Vec::new();

    for _ in 0..2 {
        let d = Rc::clone(&data);
        handles.push(thread::spawn(move || d.len()));
    }

    handles.into_iter().map(|h| h.join().unwrap()).sum()
}

