use std::sync::Arc;
use std::thread;

pub fn run() -> Vec<u32> {
    let log = Arc::new(Vec::new());
    let mut handles = Vec::new();

    for id in 0..4u32 {
        let l = Arc::clone(&log);
        handles.push(thread::spawn(move || {
            l.push(id);
        }));
    }
    for h in handles {
        h.join().unwrap();
    }

    let mut out = log.to_vec();
    out.sort();
    out
}

