use std::sync::{Arc, Mutex};
use std::thread;

pub fn run() -> Vec<u32> {
    let log = Arc::new(Mutex::new(Vec::new()));
    let mut handles = Vec::new();

    for id in 0..4u32 {
        let l = Arc::clone(&log);
        handles.push(thread::spawn(move || {
            l.lock().unwrap().push(id);
        }));
    }
    for h in handles {
        h.join().unwrap();
    }

    let mut out = log.lock().unwrap().clone();
    out.sort();
    out
}

