use std::cell::RefCell;
use std::thread;

pub fn run() -> i32 {
    let counter = RefCell::new(0);

    thread::scope(|s| {
        for _ in 0..4 {
            s.spawn(|| {
                *counter.borrow_mut() += 1;
            });
        }
    });

    counter.into_inner()
}

