use std::thread;

pub fn run() -> Vec<i32> {
    let mut data = vec![1, 2, 3, 4];

    let left = &mut data;
    let right = &mut data;

    thread::scope(|s| {
        s.spawn(move || {
            for x in left.iter_mut().take(2) {
                *x *= 10;
            }
        });
        s.spawn(move || {
            for x in right.iter_mut().skip(2) {
                *x += 100;
            }
        });
    });

    data
}

