use std::thread;

pub fn run() -> Vec<i32> {
    let mut data = vec![1, 2, 3, 4];

    {
        let (left, right) = data.split_at_mut(2);

        thread::scope(|s| {
            s.spawn(move || {
                for x in left.iter_mut() {
                    *x *= 10;
                }
            });
            s.spawn(move || {
                for x in right.iter_mut() {
                    *x += 100;
                }
            });
        });
    }

    data
}
